// Scope 2 emissions formula (GHG Protocol), per Section 11.3 of the design doc - shape 2
// ("scaled product") from the SoW's five formula shapes:
//   Scope2 (tCO2e) = electricity_consumed_kWh * emission_factor_kgCO2e_per_kWh * 0.001
//
// Written as a multiplication by the compile-time constant 0.001, rather than a
// division by 1000, to illustrate that a fixed unit-scaling factor is just another
// multiplicative operand (shape 1's "product", extended by shape 2's constant k) -
// not a distinct circuit pattern. This is worth spelling out precisely: 0.001 does
// NOT appear in the witnessed arithmetic as a literal encoded operand multiplied in.
// At 3-decimal precision, encode(0.001) = 1, so "multiplying by 0.001" contributes no
// separate factor - its entire effect is already captured by the choice of rescale
// divisor below (3.3.3). Naively multiplying by encode(0.001)=1 as a fourth operand,
// on top of that divisor, would silently double-apply the scaling and be wrong by 1000x.
//
// Precision: both inputs pinned at 3 decimal digits (fixed-point, encoded as integers).
// Rounding rule: round-half-up, applied once at the final rescale (Section 3.3.3).
//
// Public inputs: emission_factor (exact-pinned coefficient, Section 3.1), C_X, C_Y (commitments, Section 3.3.4).
// Private witnesses: electricity_consumed_kWh (encoded), salts r_x, r_y, and the
// quotient/remainder witnesses for the combined rescale step.
//
// All values are carried as Field and range-constrained explicitly (Section 3.3.1); Field
// arithmetic in a prime field has no native notion of bit width or overflow, so every
// value that must stay within a real-world domain needs its own assert_max_bit_size.

use poseidon::poseidon2::Poseidon2;

// Declared domains (Section 3.3.1). Chosen for this benchmark to comfortably cover realistic
// facility-level consumption and published emission-factor tables at 3-decimal precision.
global MAX_ELECTRICITY_KWH_ENCODED: Field = 999_999_999_999; // up to ~1 billion kWh at 3 decimals
global MAX_EMISSION_FACTOR_ENCODED: Field = 999_999; // up to ~1000.000 kgCO2e/kWh at 3 decimals

// Combined precision of two 3-decimal operands is 6 decimals; the formula's own
// scaling by 0.001 (encode(0.001) = 1 at this precision) contributes nothing further,
// so the rescale-and-round divisor is exactly 10^(6-3) = 1000, same as it would be for
// an unscaled product landing at 3-decimal output precision (shape 1, extended by k = 0.001).
global DIVISOR: Field = 1_000;
global HALF_DIVISOR: Field = 500;

fn main(
    electricity_kwh_encoded: Field, // private: X, encoded at 3 decimals
    r_x: Field,                     // private: salt for C_X
    r_y: Field,                     // private: salt for C_Y
    quotient: Field,                // private witness: floor(raw_product / DIVISOR)
    remainder: Field,               // private witness: raw_product mod DIVISOR
    round_bump: Field,              // private witness: 1 if round-half-up bumps the floor, else 0
    emission_factor_encoded: pub Field, // public: exact-pinned coefficient (3 decimals)
    c_x: pub Field,
    c_y: pub Field,
) {
    // --- 3.3.1: Encoding and range constraints ---
    electricity_kwh_encoded.assert_max_bit_size::<40>();
    assert(
        electricity_kwh_encoded.lt(MAX_ELECTRICITY_KWH_ENCODED + 1),
        "electricity out of declared domain",
    );

    emission_factor_encoded.assert_max_bit_size::<32>();
    assert(
        emission_factor_encoded.lt(MAX_EMISSION_FACTOR_ENCODED + 1),
        "emission factor out of declared domain",
    );

    // --- 3.3.4: Commitment opening constraints ---
    let computed_c_x = Poseidon2::hash([electricity_kwh_encoded, r_x], 2);
    assert(computed_c_x == c_x, "C_X does not open to the supplied X and salt");

    // --- 3.3.2 / 3.3.3: Formula evaluation, with rescale-and-round ---
    // Raw product: 3-decimal * 3-decimal = 6-decimal combined precision. The
    // formula's "* 0.001" is realized entirely by DIVISOR below, not by an extra
    // multiplication - see the module-level note on why that would double-apply it.
    let raw_product: Field = electricity_kwh_encoded * emission_factor_encoded;
    raw_product.assert_max_bit_size::<72>(); // intermediate can exceed either operand's range

    // Witnessed quotient/remainder idiom (Section 3.3.3): a = b*y + r, with 0 <= r < b.
    // DIVISOR is a compile-time constant (never zero, so no non-zero-divisor
    // constraint needed per Section 3.3.3).
    assert(raw_product == DIVISOR * quotient + remainder, "quotient/remainder do not reconstruct raw_product");
    remainder.assert_max_bit_size::<10>(); // remainder < DIVISOR (1,000 < 2^10)
    assert(remainder.lt(DIVISOR), "remainder not less than divisor");

    // Round-half-up: bump the floor quotient by 1 iff remainder >= DIVISOR/2.
    // round_bump is witnessed and constrained as boolean, then checked against the
    // actual remainder so the prover cannot pick an arbitrary rounding direction.
    assert(round_bump * (round_bump - 1) == 0, "round_bump not boolean"); // b(b-1)=0, per Section 3.3.2
    let remainder_at_or_above_half = remainder.lt(HALF_DIVISOR) == false;
    assert(
        (round_bump == 1) == remainder_at_or_above_half,
        "round_bump inconsistent with remainder",
    );

    let y_encoded: Field = quotient + round_bump;

    // --- 3.3.4: Y opened in C_Y must be the same witness as the evaluation output ---
    let computed_c_y = Poseidon2::hash([y_encoded, r_y], 2);
    assert(computed_c_y == c_y, "C_Y does not open to the computed Y and salt");
}

#[test]
fn test_scope2_basic() {
    // 1500.734 kWh * 0.421 kgCO2e/kWh * 0.001 = 0.631809014 tCO2e
    // encoded: electricity = 1500734 (3dp), factor = 421 (3dp)
    // raw_product = 1500734 * 421 = 631_809_014
    // DIVISOR = 1_000 -> quotient = 631809, remainder = 14 (< half) -> no bump -> y = 631809 (0.631809 tCO2e)
    let r_x = 111;
    let r_y = 222;
    let c_x = Poseidon2::hash([1500734, r_x], 2);
    let c_y = Poseidon2::hash([631809, r_y], 2);

    main(1500734, r_x, r_y, 631809, 14, 0, 421, c_x, c_y);
}

#[test]
fn test_scope2_round_up() {
    // electricity = 1000001 (1000.001 kWh), factor = 999999 (999.999 kgCO2e/kWh)
    // raw_product = 1000001 * 999999 = 999_999_999_999
    // DIVISOR = 1_000 -> quotient = 999999999, remainder = 999 (>= half) -> bump -> y = 1000000000
    let r_x = 333;
    let r_y = 444;
    let c_x = Poseidon2::hash([1000001, r_x], 2);
    let c_y = Poseidon2::hash([1000000000, r_y], 2);

    main(1000001, r_x, r_y, 999999999, 999, 1, 999999, c_x, c_y);
}

#[test(should_fail_with = "electricity out of declared domain")]
fn test_scope2_rejects_out_of_domain_input() {
    let r_x = 1;
    let r_y = 1;
    let too_large = MAX_ELECTRICITY_KWH_ENCODED + 1;
    let c_x = Poseidon2::hash([too_large, r_x], 2);
    let c_y = Poseidon2::hash([0, r_y], 2);

    main(too_large, r_x, r_y, 0, 0, 0, 1, c_x, c_y);
}

